/**
 * AccountTriggerHandlerTest
 *
 * @author Nick Morozov (nmorozov@corraogroup.com)
 * @since 2025-12-15
 * @group TriggerHandler
 */
@IsTest
private class AccountTriggerHandlerTest {
    @IsTest
    static void testHandleAfterInsert() {
        // Given: A new Account
        Account testAccount = new Account(
            Name = 'Test Account',
            BillingCity = 'San Francisco'
        );

        // When: Account is inserted
        Test.startTest();
        insert testAccount;
        Test.stopTest();

        // Then: Emit_Azure_Event__c flag should be set by handleAfter
        Azure_Event__c emittedEvent = [
            SELECT SF_Record_Id__c, Object_Name__c, Event_Type__c, Payload__c
            FROM Azure_Event__c
            WHERE SF_Record_Id__c = :testAccount.Id
            LIMIT 1
        ];

        System.assertNotEquals(null, emittedEvent,
            'Azure event should have been created on insert');
        System.assertEquals('AccountCreated', emittedEvent.Event_Type__c,
            'Event type should be AccountCreated on insert');
    }

    @IsTest
    static void testHandleAfterUpdate() {
        // Given: An existing Account
        Account testAccount = new Account(
            Name = 'Original Name',
            BillingCity = 'San Francisco'
        );
        insert testAccount;

        // When: Account name is changed
        Test.startTest();
        testAccount.Name = 'Updated Name';
        update testAccount;
        Test.stopTest();

        // Then: Emit_Azure_Event__c flag should have been processed
        Azure_Event__c emittedEvent = [
            SELECT SF_Record_Id__c, Object_Name__c, Event_Type__c, Payload__c
            FROM Azure_Event__c
            WHERE SF_Record_Id__c = :testAccount.Id
            LIMIT 1
        ];

        System.assertNotEquals(null, emittedEvent,
            'Azure event should have been created on name update');
        System.assertEquals('AccountUpdated', emittedEvent.Event_Type__c,
            'Event type should be AccountUpdated on name update');
    }

    @IsTest
    static void testHandleAfterUpdate_NameNotChanged() {
        // Given: An existing Account
        Account testAccount = new Account(
            Name = 'Test Account',
            BillingCity = 'San Francisco'
        );
        insert testAccount;

        // Reset flag after insert
        testAccount.Emit_Azure_Event__c = false;
        update testAccount;

        // When: Account is updated but name is NOT changed
        Test.startTest();
        testAccount.BillingCity = 'Los Angeles';
        update testAccount;
        Test.stopTest();

        // Then: Emit_Azure_Event__c flag should remain false
        List<Azure_Event__c> emittedEvents = [
            SELECT SF_Record_Id__c
            FROM Azure_Event__c
            WHERE SF_Record_Id__c = :testAccount.Id
        ];

        System.assertEquals(0, emittedEvents.size(),
            'No Azure event should be created when name is not changed');
    }

    @IsTest
    static void testMultipleAccounts() {
        // Given: Multiple accounts
        List<Account> accounts = new List<Account>{
            new Account(Name = 'Account 1'),
            new Account(Name = 'Account 2'),
            new Account(Name = 'Account 3')
        };
        insert accounts;

        // Reset flags
        for (Account acc : accounts) {
            acc.Emit_Azure_Event__c = false;
        }
        update accounts;

        // When: Only some accounts have name changed
        Test.startTest();
        accounts[0].Name = 'Updated Account 1';  // Name changed
        accounts[1].BillingCity = 'New City';    // Name NOT changed
        accounts[2].Name = 'Updated Account 3';  // Name changed
        update accounts;
        Test.stopTest();

        // Then: Only accounts with name changes should have been processed
        List<Azure_Event__c> emittedEvents = [
            SELECT SF_Record_Id__c
            FROM Azure_Event__c
            WHERE SF_Record_Id__c IN :new List<Id>{accounts[0].Id, accounts[1].Id, accounts[2].Id}
        ];

        System.assertEquals(2, emittedEvents.size(),
            'Only two Azure events should be created for accounts with name changes');
    }
}

