/**
 * AzureEventAccountContainer
 *
 * @author Nick Morozov (nmorozov@corraogroup.com)
 * @since 2025-12-06
 */

public with sharing virtual class AccountAzureEvent extends AzureEvent {
    private static final String SUBJECT = '/sobjects/Account/';
    private final String eventType;

    public AccountAzureEvent(List<SObject> newList, Map<Id, SObject> oldMap, String eventType) {
        super(newList, oldMap);

        this.eventType = eventType;
    }

    protected override Map<Id, Object> queryData() {
        Map<Id, Object> dataMap = new Map<Id, Object>();
        List<Account> accounts = [
            SELECT Emit_Azure_Event__c, Name, BillingAddress, Region__c, National_Account__c
            FROM Account
            WHERE Id IN :this.newList
        ];
        for (Account acc : accounts) {
            dataMap.put(acc.Id, new Map<String, Account>{ 'account' => acc, 'oldAccount' => (Account) this.oldMap?.get(acc.Id) });
        }
        return dataMap;
    }

    protected override Map<Id, Object> validateData(Map<Id, Object> queriedDataByContextId) {
        Map<Id, Object> validDataByContextId = new Map<Id, Object>();

        for (Id contextId : queriedDataByContextId.keySet()) {
            Object obj = queriedDataByContextId.get(contextId);
            Map<String, Account> accountMap = (Map<String, Account>) obj;
            Account account = accountMap.get('account');
            Account old = accountMap.get('oldAccount');

            if (account.Name != old?.Name || account.Emit_Azure_Event__c != old?.Emit_Azure_Event__c) {
                validDataByContextId.put(contextId, obj);
            }
        }

        return validDataByContextId;
    }

    public override String getType() {
        return AccountDataProperty.class.getName();
    }

    public override String getSubject() {
        return SUBJECT;
    }

    public override String getEventType() {
        return this.eventType;
    }

    // Extend for future versions
    public virtual class AccountDataProperty extends AzureEvent.DataProperty {
        @AuraEnabled
        public Payload_V1 values;

        @AuraEnabled
        public Payload_V1 oldValues;

        public override void mapDatum(Object validDatum) {
            Map<String, Account> accountMap = (Map<String, Account>) validDatum;
            Account account = accountMap.get('account');
            Account oldAccount = accountMap.get('oldAccount');

            this.values = new Payload_V1(account);
            if (oldAccount != null) {
                this.oldValues = new Payload_V1(oldAccount);
            }
        }

        public override String getVersion() {
            return this.values.getVersion();
        }
    }


    // Extend for future versions
    public virtual class Payload_V1 {
        @AuraEnabled
        public String accountId;

        @AuraEnabled
        public String accountName;

        @AuraEnabled
        public String billingStreet;

        @AuraEnabled
        public String billingCity;

        @AuraEnabled
        public String billingState;

        @AuraEnabled
        public String billingPostalCode;

        @AuraEnabled
        public String billingCountry;

        @AuraEnabled
        public String region;

        @AuraEnabled
        public Boolean national;

        public Payload_V1(Account account) {
            this.accountId = account.Id;
            this.accountName = account.Name;

            if (account.BillingAddress != null) {
                this.billingStreet = account.BillingAddress.getStreet();
                this.billingCity = account.BillingAddress.getCity();
                this.billingState = account.BillingAddress.getState();
                this.billingPostalCode = account.BillingAddress.getPostalCode();
                this.billingCountry = account.BillingAddress.getCountry();
            }

            this.region = account.Region__c;
            this.national = account.National_Account__c;
        }

        public String getVersion() {
            return '1';
        }
    }
}

