    72→            DataProperty dto = (DataProperty) Type.forName(this.getType()).newInstance();
    73→            Object datum = validatedDataByContextId.get(contextId);
    74→            dto.mapDatum(datum);
    75→            EventGridDTO eventDto = new EventGridDTO(contextId, dto, this.getSubject(), this.getEventType());
